{
  "concept": "Ring strain in cycloalkanes varies irregularly with ring size: three- and four-membered rings are enormously strained, cyclohexane is strain-free, medium rings (8–13) carry moderate transannular strain, and large rings return to zero strain.",
  "figureType": "bar_chart",
  "elements": [
    "Vertical bar chart on a pale blue plot field with a white outer background",
    "Left y-axis labeled 'Strain energy (kJ/mol)' from 0 to 120 in steps of 20",
    "Horizontal gridlines at 20, 40, 60, 80, 100, 120 kJ/mol",
    "Right y-axis labeled '(kcal/mol)' from 0 to 28.7 with tick labels 0, 4.8, 9.6, 14.3, 19.1, 23.9",
    "X-axis labeled 'Ring size' with integer ticks 3 through 14",
    "Twelve x-positions; ten solid medium-blue bars at ring sizes 3, 4, 5, 7, 8, 9, 10, 11, 12, 13",
    "Bar heights (kJ/mol): 3≈115, 4≈110, 5≈26, 7≈25, 8≈40, 9≈53, 10≈50, 11≈46, 12≈10, 13≈22",
    "Zero-strain markers at ring sizes 6 and 14: a short downward arrow ending at the baseline with the numeral '0' above it, replacing a bar",
    "Baseline axis line at y = 0",
    "Readout annotation (interactive) showing selected ring size with its kJ/mol and kcal/mol values",
    "Optional highlight band grouping the medium rings (8–13) when discussed"
  ],
  "interactions": [
    {
      "id": "ringSize",
      "type": "slider",
      "label": "Ring size (n carbons)",
      "range": [3, 14, 1],
      "default": 3,
      "teaches": "Reading strain energy for one ring at a time in both kJ/mol and kcal/mol, and feeling that the value jumps up and down rather than trending smoothly as the ring grows."
    },
    {
      "id": "zeroStrainFocus",
      "type": "click",
      "teaches": "That the missing bars at ring sizes 6 and 14 are not missing data but genuine zeros — cyclohexane and large rings adopt geometries with no angle, torsional, or transannular strain."
    },
    {
      "id": "strainRegions",
      "type": "toggle",
      "label": "Strain regions",
      "options": ["Off", "Small / Common / Medium / Large"],
      "default": "Off",
      "teaches": "That the jagged profile organizes into four classic categories — small rings (3–4, angle strain), common rings (5–7, near strain-free), medium rings (8–13, transannular strain), and large rings (14+, strain-free)."
    }
  ],
  "demo_steps": [
    {
      "title": "The whole landscape",
      "narration": "Twelve cycloalkanes, one bar each. The profile is jagged: two towering bars on the left, a deep valley, a broad secondary hump, and zeros at 6 and 14.",
      "state": { "ringSize": 3, "strainRegions": "Off" }
    },
    {
      "title": "Small rings: angle strain dominates",
      "narration": "Slide to 3 and 4. Cyclopropane carries about 115 kJ/mol and cyclobutane about 110 — bond angles forced far below 109.5° plus eclipsing interactions make these rings the most strained of all.",
      "state": { "ringSize": 4, "strainRegions": "Off" }
    },
    {
      "title": "The collapse at cyclohexane",
      "narration": "Move to 5, then 6. Strain plunges to ~26 kJ/mol at cyclopentane and to exactly zero at cyclohexane — click the arrow at 6 to see that the chair conformation relieves all angle and torsional strain.",
      "state": { "ringSize": 6, "strainRegions": "Off" }
    },
    {
      "title": "Medium rings climb back up",
      "narration": "From 7 onward strain rises again, peaking near 53 kJ/mol at cyclononane. These medium rings suffer transannular strain — hydrogens across the ring crowding into each other.",
      "state": { "ringSize": 9, "strainRegions": "Off" }
    },
    {
      "title": "Large rings relax",
      "narration": "By 12 and 13 strain falls off, and at 14 it is zero again: large rings are floppy enough to adopt strain-free conformations like extended alkane chains.",
      "state": { "ringSize": 14, "strainRegions": "Off" }
    },
    {
      "title": "Four regimes, one picture",
      "narration": "Turn on the region shading: small (3–4), common (5–7), medium (8–13), and large (14+). The irregular bar heights are really four different physical causes of strain acting in different size ranges.",
      "state": { "ringSize": 14, "strainRegions": "Small / Common / Medium / Large" }
    }
  ],
  "keyInsight": "Ring strain does not decrease smoothly as rings get bigger — it collapses to zero at cyclohexane, rebounds in the medium rings because of transannular crowding, and only vanishes again once the ring is large enough to behave like an open chain.",
  "reconstructionNotes": "Recreate as a Chart.js vertical bar chart: pale blue (#e8f4fb) plot area, medium-blue bars (#1a75bc) with thin darker outlines, white page background, black axis text. Left axis 'Strain energy (kJ/mol)' 0–120 step 20 with light gray horizontal gridlines; right axis '(kcal/mol)' 0–28.7 with ticks 0, 4.8, 9.6, 14.3, 19.1, 23.9 (same physical scale, 1 kcal = 4.184 kJ). X-axis 'Ring size' ticks 3–14, bars at all positions except 6 and 14, where a short thin black downward arrow tipped at the baseline carries a '0' label above it. Bar silhouette must read: two very tall bars at 3 and 4, sharp drop to short bars at 5 and 7, a rising hump 8→9 peaking ~53, gentle decline 10, 11, a low bar at 12, a modest bar at 13. Selected bar (slider) turns a saturated highlight color (e.g. orange #e8730c) with a floating readout box giving 'n = X · YY kJ/mol · ZZ kcal/mol'; non-selected bars dim slightly. Clicking a zero marker at 6 or 14 thickens and reddens the arrow, pulses the '0', and dims all bars except the immediate neighbors so the contrast with adjacent strained rings stays visible. Region toggle overlays four translucent vertical bands behind the bars with small top labels: 'Small (angle strain)', 'Common', 'Medium (transannular)', 'Large'."
}

